const binProp = items[0].binary && items[0].binary.photo ? 'photo' : Object.keys(items[0].binary || {})[0];
if (!binProp) throw new Error('No photo binary found on the request. Expected multipart field name "photo".');
const buffer = await this.helpers.getBinaryDataBuffer(0, binProp);
const base64 = buffer.toString('base64');
const mime = items[0].binary[binProp].mimeType || 'image/jpeg';
return [{ json: { imageDataUri: 'data:' + mime + ';base64,' + base64 } }];

const raw = items[0].json.choices && items[0].json.choices[0] && items[0].json.choices[0].message
  ? items[0].json.choices[0].message.content
  : '';
const match = raw.match(/\{[\s\S]*\}/);
let title = '';
try { title = JSON.parse(match ? match[0] : raw).title || ''; } catch (e) { title = String(raw).trim(); }
if (!title) throw new Error('Could not parse a game title from the vision model response: ' + raw);
return [{ json: { guessedTitle: title } }];

const xml = items[0].json.data || items[0].json;
const text = typeof xml === 'string' ? xml : JSON.stringify(xml);
const itemRe = /<item[^>]*id="(\d+)"[^>]*>([\s\S]*?)<\/item>/g;
const nameRe = /<name[^>]*value="([^"]*)"/;
const yearRe = /<yearpublished[^>]*value="([^"]*)"/;
const results = [];
let m;
while ((m = itemRe.exec(text)) && results.length < 5) {
  const id = m[1];
  const body = m[2];
  const nameMatch = body.match(nameRe);
  const yearMatch = body.match(yearRe);
  results.push({ bggId: Number(id), title: nameMatch ? nameMatch[1] : 'Unknown', yearPublished: yearMatch ? yearMatch[1] : '' });
}
return [{ json: { candidates: results } }];

const prev = $('Code - Parse Search XML').first().json.candidates;
const xml = items[0].json.data || items[0].json;
const text = typeof xml === 'string' ? xml : JSON.stringify(xml);
const itemRe = /<item[^>]*id="(\d+)"[^>]*>([\s\S]*?)<\/item>/g;
const thumbRe = /<thumbnail>([^<]*)<\/thumbnail>/;
const thumbs = {};
let m;
while ((m = itemRe.exec(text))) {
  const id = m[1];
  const body = m[2];
  const t = body.match(thumbRe);
  if (t) thumbs[id] = t[1];
}
const merged = prev.map(c => ({ ...c, thumbnail: thumbs[String(c.bggId)] || null }));
return [{ json: { candidates: merged } }];
